args.CommandLine:
"Add-Type -AssemblyName System.Drawing
$path = "C:\Users\bssho\.gemini\antigravity\brain\db6951ab-5d8c-4686-8ceb-30f7edc5429b\wide_angle_mirror_comparison_1_kr_1792490701085.jpg"
$bmp = [System.Drawing.Bitmap]::FromFile($path)
Write-Output "Width: $($bmp.Width), Height: $($bmp.Height)"
# Find the white bottom-half of the badge in region x: 450..650, y: 1000..1150
for ($y = 1040; $y -lt 1120; $y += 2) {
  $line = "$y : "
  for ($x = 470; $x -lt 620; $x += 5) {
    $c = $bmp.GetPixel($x, $y)
    if ($c.R -gt 220 -and $c.G -gt 220 -and $c.B -gt 220) { $line += "#" }
    elseif ($c.B -gt 100 -and $c.R -lt 60) { $line += "B" }
    else { $line += "." }
  }
  Write-Output $line
}
$bmp.Dispose()"
